  "resources.tipsLead": { en: "Plain-English guidance on the topics that matter most to Maryland individuals and small business owners.", ar: "إرشادات مبسطة حول أهم المواضيع التي تهم الأفراد وأصحاب الشركات الصغيرة في ماريلاند." },
