  "checklist.tagsIntro": { en: "Check everything that applies — your personalized list below updates instantly as you go.", ar: "حدّد كل ما ينطبق عليك — تتحدّث قائمتك المخصصة أدناه فورًا مع كل اختيار." },
  "checklist.tag.selfEmployed": { en: "Self-employed or freelance income", ar: "دخل من العمل الحر أو المستقل" },
  "checklist.tag.newBusiness": { en: "Started a new business this year", ar: "أسّست عملًا جديدًا هذا العام" },
  "checklist.tag.property": { en: "Rental property or sold a home", ar: "عقار مؤجّر أو بيع منزل" },
  "checklist.tag.lifeChange": { en: "Marriage, divorce, or a new dependent", ar: "زواج أو طلاق أو معال جديد" },
  "checklist.tag.payroll": { en: "I have employees or contractors", ar: "لدي موظفون أو مقاولون" },
  "checklist.resultsHeading": { en: "Your personalized checklist", ar: "قائمتك المخصصة" },
  "checklist.generalNote": { en: "This list updates automatically as you check boxes above — everyone needs the items below, plus anything specific to your situation.", ar: "تتحدّث هذه القائمة تلقائيًا كلما حدّدت خيارًا أعلاه — يحتاج الجميع إلى العناصر أدناه، بالإضافة إلى ما يخص وضعك الخاص." },
  "checklist.emailListHeading": { en: "Want this emailed to you?", ar: "هل ترغب في استلامها عبر البريد الإلكتروني؟" },
  "checklist.emailListNote": { en: "We'll send this exact list to your inbox — handy to check off as you gather everything.", ar: "سنرسل هذه القائمة بالضبط إلى بريدك — مفيدة لتتبّع ما جمعته." },

  "checklist.item.priorReturn": { en: "A copy of last year's tax return", ar: "نسخة من إقرار العام الماضي" },
  "checklist.item.photoId": { en: "Government-issued photo ID", ar: "هوية شخصية صادرة عن جهة حكومية" },
  "checklist.item.ssnCards": { en: "Social Security cards or ITIN letters for you and your dependents", ar: "بطاقات الضمان الاجتماعي أو خطابات ITIN لك ولمعاليك" },
  "checklist.item.bankInfo": { en: "Bank account and routing number, for direct deposit of any refund", ar: "رقم الحساب البنكي ورقم التوجيه، لإيداع أي مبلغ مسترد مباشرة" },
  "checklist.item.1099s": { en: "Any 1099-NEC or 1099-K forms you received", ar: "أي نماذج 1099-NEC أو 1099-K استلمتها" },
  "checklist.item.businessIncome": { en: "Records of business income (invoices, deposit records)", ar: "سجلات دخل الأعمال (فواتير، سجلات الإيداعات)" },
  "checklist.item.businessExpenses": { en: "Business expense records or receipts", ar: "سجلات أو إيصالات مصاريف الأعمال" },
  "checklist.item.mileageLog": { en: "A mileage log, if you're claiming vehicle use", ar: "سجل المسافات المقطوعة، إذا كنت تطالب باستخدام مركبة" },
  "checklist.item.homeOffice": { en: "Home office measurements, if claiming a home office deduction", ar: "قياسات مكتب المنزل، إذا كنت تطالب بخصم مكتب منزلي" },
  "checklist.item.einLetter": { en: "Your EIN confirmation letter (IRS Form CP 575)", ar: "خطاب تأكيد رقم EIN (نموذج CP 575 من مصلحة الضرائب)" },
  "checklist.item.articles": { en: "Articles of Organization or Incorporation", ar: "عقد التأسيس (Articles of Organization/Incorporation)" },
  "checklist.item.operatingAgreement": { en: "Operating Agreement or Bylaws", ar: "اتفاقية التشغيل أو النظام الأساسي" },
  "checklist.item.licenses": { en: "State or local business license documents", ar: "مستندات التراخيص التجارية الحكومية أو المحلية" },
  "checklist.item.closingStatement": { en: "Closing disclosure or settlement statement", ar: "بيان الإفصاح عند الإغلاق أو بيان التسوية" },
  "checklist.item.1098": { en: "Form 1098 (mortgage interest statement)", ar: "نموذج 1098 (بيان فوائد الرهن العقاري)" },
  "checklist.item.rentalRecords": { en: "Rental income and expense records", ar: "سجلات دخل ومصاريف الإيجار" },
  "checklist.item.depreciationSchedule": { en: "Prior year's depreciation schedule, if this isn't your first year renting", ar: "جدول الإهلاك للعام السابق، إذا لم يكن هذا أول عام لك في التأجير" },
  "checklist.item.maritalDocs": { en: "Marriage certificate or divorce decree, if your filing status changed", ar: "شهادة الزواج أو حكم الطلاق، إذا تغيّرت حالتك الاجتماعية للتقديم" },
